package com.yeyamo_mobile.api.gamification_service.infrastructure.messaging;import static org.junit.jupiter.api.Assertions.*;import java.util.UUID;import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;
class EventXpPolicyTest{private final ObjectMapper mapper=new ObjectMapper();private final EventXpPolicy policy=new EventXpPolicy();@Test void mapsPublishedContent()throws Exception{var a=policy.map(event("content.post.published","{\"postId\":\"p1\",\"authorId\":\"u1\"}")).orElseThrow();assertEquals(20,a.points());assertEquals("POST",a.counterType());}@Test void mapsCheckinToPassportDestination()throws Exception{var a=policy.map(event("interaction.checkin.created","{\"checkInId\":\"c1\",\"catalogAssetId\":\"a1\",\"userId\":\"u1\"}")).orElseThrow();assertEquals(30,a.points());assertEquals("a1",a.destinationId());}@Test void mapsBookingContract()throws Exception{var a=policy.map(event("booking.confirmed","{\"bookingId\":\"b1\",\"userId\":\"u1\"}")).orElseThrow();assertEquals(50,a.points());assertEquals("BOOKING",a.reason());}@Test void ignoresUnrewardedEvents()throws Exception{assertTrue(policy.map(event("content.post.updated","{}")).isEmpty());}private com.fasterxml.jackson.databind.JsonNode event(String type,String payload)throws Exception{return mapper.readTree("{\"eventId\":\""+UUID.randomUUID()+"\",\"eventType\":\""+type+"\",\"eventVersion\":1,\"payload\":"+payload+"}");}}
